positions = function () { const result = calculatePositions(); const maxDepth = result.maxDepth; const totalSlots = 2 ** (maxDepth + 1); const slotGap = 180; const digitValue = (digit) => digit === '2' ? 1 : 0; layout.width = totalSlots * slotGap; state.people.forEach((person) => { const depth = Math.max(0, String(person.id).length - 1); const digits = String(person.id).split('').map(digitValue); const prefixIndex = digits.reduce((value, digit) => value * 2 + digit, 0); const subtreeSlots = 2 ** (maxDepth - depth); const centerSlot = prefixIndex * subtreeSlots + subtreeSlots / 2; const position = result.positionsMap.get(person.id); if (position) { position.x = centerSlot * slotGap; position.y = layout.rows + (maxDepth - depth) * layout.generationGap } }); const mainPerson = state.people.find((person) => person.rol === 'yo'); const sibling = state.people.find((person) => person.rol === 'hermano'); if (mainPerson && sibling) { const mainPosition = result.positionsMap.get(mainPerson.id); const siblingPosition = result.positionsMap.get(sibling.id); const family = state.families.find(({ hijos = [] }) => hijos.includes(mainPerson.id) && hijos.includes(sibling.id)); const parentPositions = family?.padres.map((id) => result.positionsMap.get(id)).filter(Boolean) || []; if (mainPosition && siblingPosition && parentPositions.length) { const parentCenter = parentPositions.reduce((total, parent) => total + parent.x, 0) / parentPositions.length; mainPosition.x = parentCenter - 80; siblingPosition.x = parentCenter + 80 } } return result }
