function getPerson(id) { return state.people.find((person) => person.id === id) }
function familyParents(id) { return [...new Set(state.families.filter((family) => family.hijos.includes(id)).flatMap((family) => family.padres))] }
function familyChildren(id) { return [...new Set(state.families.filter((family) => family.padres.includes(id)).flatMap((family) => family.hijos))] }
function partnerId(id) { const couple = state.couples.find((pair) => pair.includes(id)); return couple ? couple.find((personId) => personId !== id) : null }
function fullName(person) { return `${person.nombre} ${person.apellidos}` }
function age(person) { const end = person.fallecimiento ? new Date(`${person.fallecimiento}T00:00:00`) : new Date(); const start = new Date(`${person.nacimiento}T00:00:00`); let years = end.getFullYear() - start.getFullYear(); if (end < new Date(end.getFullYear(), start.getMonth(), start.getDate())) years -= 1; return years }
function years(person) { const birth = person.nacimiento && person.nacimiento !== 'X' && person.nacimiento !== '1X' ? new Date(person.nacimiento).getFullYear() : '?'; const death = person.fallecimiento && person.fallecimiento !== 'X' && person.fallecimiento !== '1X' ? new Date(person.fallecimiento).getFullYear() : person.fallecimiento ? '?' : 'presente'; return `${birth} - ${death}` }
function initials(person) { return `${person.nombre[0]}${person.apellidos.split(' ')[0][0]}` }
function avatar(person) { const feminine = person.genero === 'F'; const skinTone = feminine ? '#f6d1b1' : '#f0bb8f'; const hair = feminine ? '<path d="M10 20C9 10 15 5 25 5s16 5 15 15H10Z" fill="#5f4b43"/><path d="M10 19v17c-4 0-6-3-6-7s2-8 6-10m30 0c4 2 6 6 6 10s-2 7-6 7V19" fill="#5f4b43"/>' : '<path d="M10 22C9 10 15 5 25 5s16 5 15 17H10Z" fill="#3e4a4e"/>'; return `<span class="avatar avatar-${person.genero?.toLowerCase() || 'o'}"><svg viewBox="0 0 50 50" aria-label="Avatar ${feminine ? 'mujer' : 'hombre'}" role="img"><circle cx="25" cy="26" r="14" fill="${skinTone}"/>${hair}<circle cx="20" cy="25" r="1.5" fill="#263c4a"/><circle cx="30" cy="25" r="1.5" fill="#263c4a"/><path d="M21 32c2 2 6 2 8 0" fill="none" stroke="#b86c5e" stroke-width="1.5" stroke-linecap="round"/><path d="M11 48c1-9 7-13 14-13s13 4 14 13" fill="${feminine ? '#d88975' : '#6e9f9b'}"/></svg><small>${initials(person)}</small></span>` }
function generationLevels() {
  const depths = state.people.map((person) => Math.max(0, String(person.id).length - 1));
  const maxDepth = Math.max(0, ...depths);
  return new Map(state.people.map((person) => [person.id, maxDepth - Math.max(0, String(person.id).length - 1)]));
}
function positions() { const levels = generationLevels(); const maxDepth = Math.max(0, ...levels.values()); const groups = Array.from({ length: maxDepth + 1 }, () => []); state.people.forEach((person) => groups[levels.get(person.id)].push(person)); const positionsMap = new Map(); groups.forEach((group, depth) => { const spacing = Math.max(220, Math.min(300, (layout.width - 120) / Math.max(group.length, 1))); const start = layout.centerX - ((group.length - 1) * spacing) / 2; group.forEach((person, index) => positionsMap.set(person.id, { x: start + index * spacing, y: layout.rows + depth * layout.generationGap })) }); return { positionsMap, maxDepth } }
function render() { const { positionsMap, maxDepth } = positions(); const canvasHeight = layout.rows + maxDepth * layout.generationGap + 160; const nodes = $('#nodes'); const svg = $('#connections'); $('#treeCanvas').style.height = `${canvasHeight}px`; nodes.innerHTML = state.people.map((person) => { const pos = positionsMap.get(person.id); return `<button class="person-card ${person.fallecimiento ? 'is-deceased' : ''} ${person.id === state.selectedId ? 'is-selected' : ''}" data-id="${person.id}" style="left:${pos.x - 95}px;top:${pos.y}px"><div class="card-top">${avatar(person)}<span class="life-state">${person.fallecimiento ? '†' : '●'}</span></div><strong>${fullName(person)}</strong><span class="person-years">${years(person)}</span><span class="card-arrow">${icon('arrow')}</span></button>` }).join(''); svg.setAttribute('viewBox', `0 0 ${layout.width} ${canvasHeight}`); svg.innerHTML = connections(positionsMap); $('#peopleCount').textContent = state.people.length; $('#generationCount').textContent = maxDepth + 1; $('#zoomLabel').textContent = `${Math.round(state.scale * 100)}%`; applyTransform(); renderDetails() }
function connections(positionsMap) { const paths = []; const couples = new Set(); const familyGroups = new Map(); state.people.forEach((person) => { if (person.parejaId && getPerson(person.parejaId) && !couples.has(person.id) && !couples.has(person.parejaId)) { const first = positionsMap.get(person.id); const second = positionsMap.get(person.parejaId); if (first && second) paths.push(`<line class="couple-line" x1="${first.x}" y1="${first.y + 77}" x2="${second.x}" y2="${second.y + 77}"/>`); couples.add(person.id); couples.add(person.parejaId) } const parentIds = [person.padreId, person.madreId].filter(Boolean).sort(); if (parentIds.length) { const key = parentIds.join('|'); if (!familyGroups.has(key)) familyGroups.set(key, { parentIds, children: [] }); familyGroups.get(key).children.push(person.id) } }); familyGroups.forEach(({ parentIds, children }) => { const parents = parentIds.map((id) => positionsMap.get(id)).filter(Boolean); const childPositions = children.map((id) => positionsMap.get(id)).filter(Boolean); if (!parents.length || !childPositions.length) return; const parentBottom = Math.max(...parents.map((parent) => parent.y + 154)); const childTop = Math.min(...childPositions.map((child) => child.y)); const gap = Math.max(24, childTop - parentBottom); const upperBus = parentBottom + Math.min(24, gap / 3); const lowerBus = childTop - Math.min(24, gap / 3); const parentFrom = Math.min(...parents.map((parent) => parent.x)); const parentTo = Math.max(...parents.map((parent) => parent.x)); const childFrom = Math.min(...childPositions.map((child) => child.x)); const childTo = Math.max(...childPositions.map((child) => child.x)); const trunkX = (parentFrom + parentTo) / 2; const bridgeFrom = Math.min(trunkX, childFrom); const bridgeTo = Math.max(trunkX, childTo); parents.forEach((parent) => { paths.push(`<path class="parent-branch" d="M ${parent.x} ${parentBottom - 1} V ${upperBus}"/>`); paths.push(`<circle class="connection-dot" cx="${parent.x}" cy="${parentBottom}" r="3"/>`) }); if (parents.length > 1) paths.push(`<path class="parent-branch" d="M ${parentFrom} ${upperBus} H ${parentTo}"/>`); paths.push(`<path class="parent-line" d="M ${trunkX} ${upperBus} V ${lowerBus}"/>`); paths.push(`<path class="parent-branch" d="M ${bridgeFrom} ${lowerBus} H ${bridgeTo}"/>`); childPositions.forEach((child) => { paths.push(`<path class="parent-branch" d="M ${child.x} ${lowerBus} V ${child.y + 1}"/>`); paths.push(`<circle class="connection-dot" cx="${child.x}" cy="${child.y}" r="3"/>`) }) }); return paths.join('') }
function applyTransform() { const tree = $('#treeCanvas'); tree.style.left = `${state.pan.x}px`; tree.style.top = `${state.pan.y}px`; tree.style.transform = `scale(${state.scale})` }
function centerOnMainPerson() { const mainPerson = state.people.find((person) => person.rol === 'yo') || state.people[0]; const position = mainPerson && positions().positionsMap.get(mainPerson.id); if (!position) return; const viewport = $('#viewport'); state.pan = { x: viewport.clientWidth / 2 - position.x * state.scale, y: viewport.clientHeight / 2 - position.y * state.scale }; applyTransform() }
const nativeFetch = window.fetch.bind(window)
window.fetch = (resource, options) => { const url = typeof resource === 'string' ? resource : resource.url; if (!url.includes('./familia.json')) return nativeFetch(resource, options); const localUrl = url.replace('./familia.json', './familia.local.json'); return nativeFetch(localUrl, options).then((response) => response.ok ? response : nativeFetch(resource, options)) }
const touchPointers = new Map()
