async function loadFamilyRelations() { try { const response = await fetch(`./familia.json?actualizado=${Date.now()}`, { cache: 'no-store' }); if (!response.ok) throw new Error(`HTTP ${response.status}`); const data = await response.json(); if (Array.isArray(data)) throw new Error('Usa el formato personas, familias y parejas'); const people = data.personas; const families = data.familias; const couples = data.parejas; if (!Array.isArray(people) || !Array.isArray(families) || !Array.isArray(couples)) throw new Error('El JSON debe contener personas, familias y parejas'); const signature = JSON.stringify({ people, families, couples }); if (signature !== state.lastSignature) { state.people = people; state.families = families; state.couples = couples; state.lastSignature = signature; if (!getPerson(state.selectedId)) state.selectedId = null; render() } $('#syncStatus').textContent = `familia.json · ${new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })}`; $('#loadError').textContent = '' } catch (error) { $('#syncStatus').textContent = 'No se pudo cargar familia.json'; $('#loadError').innerHTML = `<strong>No se pudo leer familia.json.</strong><span>Revisa las secciones personas, familias y parejas de <b>familia.json</b>.</span>`; console.error(error) } }
async function loadFamilyData() { try { const response = await fetch(`./familia.json?actualizado=${Date.now()}`, { cache: 'no-store' }); if (!response.ok) throw new Error(`HTTP ${response.status}`); const data = await response.json(); const people = data.personas; const families = data.familias; if (!Array.isArray(people) || !Array.isArray(families)) throw new Error('El JSON debe contener personas y familias'); const signature = JSON.stringify({ people, families }); if (signature !== state.lastSignature) { state.people = people; state.families = families; state.couples = []; state.lastSignature = signature; if (!getPerson(state.selectedId)) state.selectedId = null; render() } $('#syncStatus').textContent = `familia.json · ${new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })}`; $('#loadError').textContent = '' } catch (error) { $('#syncStatus').textContent = 'No se pudo cargar familia.json'; $('#loadError').textContent = 'Revisa las secciones personas y familias de familia.json.'; console.error(error) } }
$('#viewport').addEventListener('pointermove', (event) => { if (!state.dragging) return; state.pan.y = event.clientY - state.dragStart.y; applyTransform() }); loadFamilyData().then(centerOnMainPerson); setInterval(loadFamilyData, 2000)
